-- CSAP Apidoc 数据库模式建表脚本 / schema for the database rule store (mysql)
-- 与 csap-apidoc-go 共用同一套表;表前缀 csap.apidoc.database.table-prefix 默认 csap_apidoc_
-- Shared with csap-apidoc-go. Generated by DatabaseRuleStore.schemaScript, do not edit by hand.

CREATE TABLE csap_apidoc_rule (
    service VARCHAR(128) NOT NULL,
    rule_key VARCHAR(512) NOT NULL,
    rules LONGTEXT NOT NULL,
    version BIGINT NOT NULL,
    updated_by VARCHAR(128) NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (service, rule_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE csap_apidoc_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    service VARCHAR(128) NOT NULL,
    rule_key VARCHAR(512) NOT NULL,
    before_rules LONGTEXT,
    after_rules LONGTEXT,
    version BIGINT NOT NULL,
    updated_by VARCHAR(128) NOT NULL,
    updated_at BIGINT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX csap_apidoc_history_key ON csap_apidoc_history (service, rule_key, id);

CREATE TABLE csap_apidoc_meta (
    service VARCHAR(128) NOT NULL PRIMARY KEY,
    version BIGINT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- MCP 审计表:只有 csap.apidoc.mcp.audit.store=database 时才使用,规则存储不依赖它
-- MCP audit table: used only when csap.apidoc.mcp.audit.store=database

CREATE TABLE csap_apidoc_mcp_audit (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    service VARCHAR(128) NOT NULL,
    at BIGINT NOT NULL,
    caller VARCHAR(128),
    remote_address VARCHAR(64),
    tool VARCHAR(128),
    target VARCHAR(512),
    arguments LONGTEXT,
    status INT NOT NULL,
    success SMALLINT NOT NULL,
    result LONGTEXT,
    duration_ms BIGINT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX csap_apidoc_mcp_audit_service_at ON csap_apidoc_mcp_audit (service, at);

CREATE INDEX csap_apidoc_mcp_audit_at ON csap_apidoc_mcp_audit (at);

